def call_tool(name, args, registry):
    """Dispatch a tool call by name; return an error string for unknown tools."""
    if name not in registry:
        return f"error: unknown tool '{name}'"
    return registry[name](**args)

registry = {"add": lambda a, b: a + b}
print(call_tool("add", {"a": 6, "b": 7}, registry))

def run_agent(plan_fn, call_tool_fn, question, max_turns=5):
    """Run the plan -> act -> observe loop until the model gives a final answer."""
    history = [{"role": "user", "content": question}]
    for _ in range(max_turns):
        response = plan_fn(history)
        if response["type"] == "final_answer":
            return response["content"]
        observation = call_tool_fn(response["name"], response["args"])
        history.append({"role": "tool", "content": observation})
    return "error: max turns reached"

def fake_plan(history):
    if len(history) < 3:
        return {"type": "tool_call", "name": "add", "args": {"a": 6, "b": 7}}
    return {"type": "final_answer", "content": "13"}

def fake_call_tool(name, args):
    return args["a"] + args["b"]

print(run_agent(fake_plan, fake_call_tool, "What is 6 + 7?"))
